/**
 * Rulebook 1.33.0 §25 / §26 Reports (owner 6 Nov): the overtime, price work and expenses report content in the invoice
 * / timesheet family — header (company, person, period, generated by / at), table columns and rows, totals, a declined
 * line at 0h "Declined by {name}", the out-of-date mark, and one evidence page per piece headed by its item. Field names
 * match iOS `OvertimeReportPDFLayout` / `PayeClaimReportLayout`.
 */
import assert from 'node:assert/strict'
import test from 'node:test'
import {
  EXPENSES_REPORT_COLUMNS,
  OVERTIME_REPORT_COLUMNS,
  OVERTIME_REPORT_OUT_OF_DATE_NOTE,
  PRICE_WORK_REPORT_COLUMNS,
  overtimeReportIsOutOfDate,
  overtimeReportLineDeclinedBy,
  overtimeReportRows,
  parseExpenseDocument,
  parseOvertimeReportDocument,
  parsePriceWorkDocument,
  payeClaimEvidencePages,
  payeClaimReportRows,
  payeClaimReportSnapshot,
  reportGeneratedText,
} from './index'

const ORG = 'org1'
const GENERATED_MS = Date.UTC(2026, 10, 6, 14, 5) // 6 Nov 2026 14:05 UTC = 14:05 London (GMT)

function overtimeCopy(extra: Record<string, unknown> = {}) {
  return parseOvertimeReportDocument('REP1', {
    userId: 'sam',
    userName: 'Sam Smith',
    companyName: 'Acme Ltd',
    rangeStart: '2026-10-26',
    rangeEnd: '2026-11-25',
    kind: 'overtime',
    lines: [
      { bookingId: 'B1', dayKey: '2026-11-04', jobNumber: 'J-1042', jobName: 'Riverside Flats', start: '06:30', end: '14:00', clockHours: 1, multiplier: 1.5, breakHours: 0, overtimeHours: 1.5, text: '1h × 1.5 = 1.5h' },
      { bookingId: 'B2', dayKey: '2026-11-05', jobNumber: 'J-7', jobName: '', start: '', end: '', clockHours: 0, multiplier: 1, breakHours: 0, overtimeHours: 0, text: '' },
    ],
    totals: { overtimeHours: 1.5, clockHours: 1, lineCount: 2 },
    generatedBy: 'sam',
    generatedAt: GENERATED_MS,
    ...extra,
  })
}

test('1.33.0 reportGeneratedText: organisation-zone time, the generator defaults to the report person', () => {
  assert.deepEqual(reportGeneratedText({ generatedAtMs: GENERATED_MS, timeZone: 'Europe/London', generatedBy: 'sam', userId: 'Sam', userName: 'Sam Smith' }), {
    generatedAt: '6 Nov 2026, 14:05',
    generatedBy: 'Sam Smith',
    generated: '6 Nov 2026, 14:05 by Sam Smith',
  })
  // Another generator with no resolved name: only the time; a resolved name wins.
  assert.equal(reportGeneratedText({ generatedAtMs: GENERATED_MS, generatedBy: 'admin', userId: 'sam', userName: 'Sam' }).generated, '6 Nov 2026, 14:05')
  assert.equal(reportGeneratedText({ generatedAtMs: GENERATED_MS, generatedBy: 'admin', userId: 'sam', userName: 'Sam', generatedByName: 'Ann Admin' }).generatedBy, 'Ann Admin')
  // Not back from the server yet: `nowMs`; nothing known: empty.
  assert.equal(reportGeneratedText({ nowMs: Date.UTC(2026, 6, 1, 9, 0), timeZone: 'Europe/London' }).generatedAt, '1 Jul 2026, 10:00')
  assert.deepEqual(reportGeneratedText({}), { generatedAt: '', generatedBy: '', generated: '' })
})

test('1.33.0 overtimeReportRows: header, columns, one table row per line, totals (iOS field names)', () => {
  const content = overtimeReportRows(overtimeCopy(), { timeZone: 'Europe/London' })
  assert.equal(content.documentTitle, 'Overtime report')
  assert.equal(content.companyName, 'Acme Ltd')
  assert.equal(content.personName, 'Sam Smith')
  assert.equal(content.period, 'Mon 26 Oct – Wed 25 Nov')
  assert.equal(content.generated, '6 Nov 2026, 14:05 by Sam Smith')
  assert.deepEqual(content.columns, [...OVERTIME_REPORT_COLUMNS])
  assert.deepEqual(content.columns, ['Day', 'Job', 'Start–Finish', 'Overtime'])
  assert.deepEqual(content.table[0], { bookingId: 'B1', day: 'Wed 4 Nov', job: 'J-1042 Riverside Flats', time: '06:30–14:00', overtime: '1h × 1.5 = 1.5h', note: '', declined: false })
  assert.equal(content.table[1].time, '', 'no times stored: the app shows "—"')
  assert.equal(content.table[1].job, 'J-7')
  assert.equal(content.totalLabel, 'Total overtime')
  assert.equal(content.totalValue, '1.5h')
  assert.equal(content.total, 'Total overtime: 1.5h')
  assert.equal(content.emptyMessage, 'There is no overtime in this range.')
  assert.equal(content.footer, 'Acme Ltd · Overtime report · Sam Smith')
  assert.equal(content.outOfDate, false)
  assert.equal(content.outOfDateNote, '')
  // The pre-1.33 text rows are still there for older readers.
  assert.equal(content.rows[0], 'Wed 4 Nov · J-1042 Riverside Flats · 06:30–14:00 · 1h × 1.5 = 1.5h')
})

test('1.33.0 overtimeReportRows: a declined line is 0h "Declined by {name}"; an out-of-date report is marked', () => {
  const copy = overtimeCopy()
  const declined = {
    ...copy,
    lines: [{ ...copy.lines[0], declined: true, declinedByName: 'Lee Manager' }, copy.lines[1]],
    outOfDate: true,
  }
  const content = overtimeReportRows(declined, { timeZone: 'Europe/London' })
  assert.equal(content.table[0].overtime, '0h')
  assert.equal(content.table[0].note, 'Declined by Lee Manager')
  assert.equal(content.table[0].declined, true)
  assert.equal(content.rows[0], 'Wed 4 Nov · J-1042 Riverside Flats · 06:30–14:00 · 0h · Declined by Lee Manager')
  assert.equal(content.outOfDate, true)
  assert.equal(content.outOfDateNote, OVERTIME_REPORT_OUT_OF_DATE_NOTE)
  assert.equal(overtimeReportLineDeclinedBy({ declined: true }), '')
  assert.equal(overtimeReportLineDeclinedBy({}), null)
  assert.equal(overtimeReportIsOutOfDate({ outOfDateAtMs: 1 }), true)
  assert.equal(overtimeReportIsOutOfDate({ outOfDate: false }), false)
  assert.equal(overtimeReportIsOutOfDate(null), false)
})

const evidence = (n: number, name: string, contentType: string, kind = 'photo') => ({
  path: `organizations/${ORG}/payeClaims/sam/sam_${1_700_000_000_000 + n}.${name.split('.').pop()}`,
  name,
  kind,
  contentType,
})

test('1.33.0 payeClaimReportRows: expenses header, columns and each row field on its own', () => {
  const items = [
    parseExpenseDocument('E1', { userId: 'sam', title: 'Fuel', details: 'Diesel for the van', amount: 40, date: '2026-11-04', jobNumber: 'J-9', evidence: [evidence(1, 'receipt.jpg', 'image/jpeg'), evidence(2, 'invoice.pdf', 'application/pdf', 'file')] }, { organizationId: ORG }),
  ]
  const snap = payeClaimReportSnapshot({ kind: 'expense', userId: 'sam', userName: 'Sam Smith', companyName: 'Acme Ltd', currency: 'GBP', rangeStart: '2026-10-26', rangeEnd: '2026-11-25', items, generatedBy: 'sam' })
  const content = payeClaimReportRows({ ...snap, generatedAtMs: GENERATED_MS }, { timeZone: 'Europe/London' })
  assert.equal(content.documentTitle, 'Expenses report')
  assert.equal(content.companyName, 'Acme Ltd')
  assert.equal(content.personName, 'Sam Smith')
  assert.equal(content.period, 'Mon 26 Oct – Wed 25 Nov')
  assert.equal(content.generated, '6 Nov 2026, 14:05 by Sam Smith')
  assert.deepEqual(content.columns, [...EXPENSES_REPORT_COLUMNS])
  const row = content.rows[0]
  assert.deepEqual(
    { itemId: row.itemId, date: row.date, jobNumber: row.jobNumber, name: row.name, approvedBy: row.approvedBy, amount: row.amount, description: row.description, evidenceNote: row.evidenceNote },
    { itemId: 'E1', date: 'Wed 4 Nov', jobNumber: 'J-9', name: 'Fuel', approvedBy: '', amount: '£40.00', description: 'Diesel for the van', evidenceNote: 'Evidence: 2 (receipt.jpg, invoice.pdf)' }
  )
  assert.equal(row.heading, 'Wed 4 Nov · J-9 · Fuel', 'the pre-1.33 heading is unchanged')
  assert.equal(content.totalLabel, 'Total expenses')
  assert.equal(content.totalAmount, '£40.00')
  assert.equal(content.itemCount, 1)
  assert.equal(content.evidenceCount, 2)
  assert.equal(content.footer, 'Acme Ltd · Expenses report · Sam Smith')
})

test('1.33.0 payeClaimEvidencePages: one page per piece, headed by its item and the evidence title', () => {
  const pw = parsePriceWorkDocument(
    'P1',
    { userId: 'sam', title: 'Tiling', details: 'Bathroom 2', amount: 250, startDate: '2026-11-02', endDate: '2026-11-04', jobNumber: '', approvedByUserId: 'lm', approvedByName: 'Lee Manager', evidence: [evidence(3, 'before.png', 'image/png'), evidence(4, 'audit.pdf', 'application/pdf', 'personalSiteAudit')] },
    { organizationId: ORG }
  )
  const snap = payeClaimReportSnapshot({ kind: 'priceWork', userId: 'sam', userName: 'Sam', currency: 'GBP', rangeStart: '2026-10-26', rangeEnd: '2026-11-25', items: [pw], generatedBy: 'sam' })
  const rows = payeClaimReportRows(snap)
  assert.deepEqual(rows.columns, [...PRICE_WORK_REPORT_COLUMNS])
  assert.equal(rows.rows[0].date, 'Mon 2 Nov – Wed 4 Nov')
  assert.equal(rows.rows[0].jobNumber, '—', 'an item stored before 1.30.1 has no job number')
  assert.equal(rows.rows[0].approvedBy, 'Lee Manager')
  const pages = payeClaimEvidencePages(snap)
  assert.equal(pages.length, 2)
  assert.deepEqual(
    { itemName: pages[0].itemName, date: pages[0].date, jobNumber: pages[0].jobNumber, approvedBy: pages[0].approvedBy, amount: pages[0].amount, evidenceTitle: pages[0].evidenceTitle, notes: pages[0].notes, drawAs: pages[0].drawAs },
    { itemName: 'Tiling', date: 'Mon 2 Nov – Wed 4 Nov', jobNumber: '—', approvedBy: 'Lee Manager', amount: '£250.00', evidenceTitle: 'Evidence 1 of 2: before.png', notes: ['Bathroom 2'], drawAs: 'image' }
  )
  assert.equal(pages[1].evidenceTitle, 'Evidence 2 of 2: audit.pdf (personal site audit copy)')
  // Without the kind (a pre-1.33 caller) the price work extras are left out.
  assert.equal(payeClaimEvidencePages({ items: snap.items, currency: snap.currency })[0].approvedBy, '')
})
